Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "background": "transparent",
  "padding": 5,
  "width": "container",
  "height": "container",
  "title": {
    "text": "% de pedidos com alta prob. de avaliação ≤ 2 — onde priorizar service recovery",
    "fontSize": 9,
    "fontWeight": 400,
    "color": "#A1A1AA",
    "anchor": "start",
    "offset": 4
  },
  "config": {
    "view": {
      "stroke": null
    },
    "font": "Segoe UI",
    "axis": {
      "domain": false,
      "ticks": false,
      "gridColor": "rgba(255,255,255,0.06)",
      "labelColor": "#C8C8D0",
      "titleColor": "#9aa0aa",
      "labelFontSize": 10,
      "titleFontSize": 10
    },
    "legend": {
      "disable": true
    }
  },
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "window": [
        {
          "op": "rank",
          "as": "rk"
        }
      ],
      "sort": [
        {
          "field": "Pct_Alto_Risco",
          "order": "descending"
        }
      ]
    },
    {
      "filter": "datum.rk <= 14"
    },
    {
      "calculate": "format(datum[''Pct_Alto_Risco''], ''.1%'')",
      "as": "lbl"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "bar",
        "cornerRadiusEnd": 4,
        "height": {
          "band": 0.72
        }
      },
      "encoding": {
        "color": {
          "field": "Pct_Alto_Risco",
          "type": "quantitative",
          "scale": {
            "range": [
              "#F2C94C",
              "#E5484D"
            ]
          },
          "legend": null
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "dx": 6,
        "color": "#C8C8D0",
        "fontSize": 10
      },
      "encoding": {
        "text": {
          "field": "lbl",
          "type": "nominal"
        }
      }
    }
  ],
  "encoding": {
    "y": {
      "field": "UF",
      "type": "nominal",
      "title": null,
      "sort": {
        "field": "Pct_Alto_Risco",
        "op": "max",
        "order": "descending"
      },
      "axis": {
        "labelFontSize": 10
      }
    },
    "x": {
      "field": "Pct_Alto_Risco",
      "type": "quantitative",
      "title": null,
      "axis": {
        "format": ".0%",
        "grid": true
      }
    },
    "tooltip": [
      {
        "field": "UF"
      },
      {
        "field": "Pct_Alto_Risco",
        "type": "quantitative",
        "format": ".1%"
      },
      {
        "field": "Pedidos",
        "type": "quantitative",
        "format": ",.0f"
      }
    ],
    "opacity": {
      "condition": {
        "test": "datum.__selected__ === ''off''",
        "value": 0.25
      },
      "value": 1
    }
  }
}'
